// Generated by build-sw.mjs. Only public, versioned shell files are cached.
const version = '__CACHE_VERSION__'
const precache = ['__PRECACHE__']
const shellCache = `robopark-shell-${version}`
const runtimeCache = `robopark-runtime-${version}`
const cachePrefix = 'robopark-'
const maxRuntimeEntries = 100
const hashedAsset = /^\/assets\/(?:[A-Za-z0-9_-]+\/)*[A-Za-z0-9_-]+-[A-Za-z0-9_-]{2,}\.(?:js|css|png|svg|webp|woff2?)$/

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(shellCache).then((cache) => cache.addAll(precache)))
  // Do not call skipWaiting: an open page must keep using its existing bundle.
})

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys()
    await Promise.all(names.filter((name) => name.startsWith(cachePrefix) && name !== shellCache && name !== runtimeCache)
      .map((name) => caches.delete(name)))
    await self.clients.claim()
  })())
})

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET') return
  const url = new URL(request.url)
  if (url.origin !== self.location.origin || url.pathname.startsWith('/api/')) return

  if (request.mode === 'navigate') {
    event.respondWith(fetch(request).catch(async () => {
      const cache = await caches.open(shellCache)
      return cache.match('/offline.html')
    }))
    return
  }
  if (url.search || !hashedAsset.test(url.pathname)) return
  event.respondWith((async () => {
    const cached = await caches.match(request)
    if (cached) return cached
    const response = await fetch(request)
    const contentType = response.headers.get('content-type') || ''
    if (response.ok && response.type !== 'opaque' && /^(?:text\/css|(?:application|text)\/javascript|image\/(?:png|svg\+xml|webp)|font\/woff2?)/i.test(contentType)) {
      const cache = await caches.open(runtimeCache)
      await cache.put(request, response.clone())
      const keys = await cache.keys()
      await Promise.all(keys.slice(0, Math.max(0, keys.length - maxRuntimeEntries)).map((key) => cache.delete(key)))
    }
    return response
  })())
})
